// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint96 depositAmount, uint96 withdrawAmount) public {
        depositAmount = uint96(bound(depositAmount, 1, type(uint96).max));
        withdrawAmount = uint96(bound(withdrawAmount, 1, depositAmount));

        address user = address(0x1234);
        vm.deal(user, depositAmount);

        vm.prank(user);
        c.addToBalance{value: depositAmount}();

        uint256 ethBefore = user.balance;
        uint256 balanceBefore = c.getBalance(user);

        vm.prank(user);
        c.withdrawBalance();

        uint256 ethAfter = user.balance;
        uint256 balanceAfter = c.getBalance(user);

        assertTrue(balanceAfter == 0 && ethAfter - ethBefore == balanceBefore);
    }
}
